'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','progression-data.js','progression-engine.js','quest-hubs.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window,{tasks,hubs}=w.PHOENIX_ROUTE,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,hubs),state={progress:engine.init(),completed:{}};return {model:w.PhoenixNearbyModel,tasks,engine,state};}
test('optional counts retain blocked stops as unfinished and missed stops in total without claiming all completed',()=>{const x=setup();x.state.progress.manual.arrival=true;x.state.progress.failed['q-missing']=true;x.state.completed['poi-4']=true;const before=JSON.stringify(x.state),c=x.model.counts(['q-beast','q-missing','poi-4'],x);assert.equal(c.total,3);assert.equal(c.unfinished,1);assert.equal(c.allCompleted,false);assert.equal(x.model.state('q-beast',x).blocked,true);assert.equal(JSON.stringify(x.state),before);});
test('missed entries move below available and completed entries; correcting failure restores original route order',()=>{const x=setup(),ids=['q-missing','poi-4','pop-cemetery'];x.state.progress.failed['q-missing']=true;assert.deepEqual(Array.from(x.model.routeOrder(ids,x)),['poi-4','pop-cemetery','q-missing']);delete x.state.progress.failed['q-missing'];assert.deepEqual(Array.from(x.model.routeOrder(ids,x)),ids);x.state.completed['poi-4']=true;assert.equal(x.model.state('poi-4',x).complete,true);assert.deepEqual(Array.from(x.model.routeOrder(ids,x)),ids);});
test('all-completed is distinct from zero unfinished with missed outcomes; prerequisites link to real authored stages',()=>{const x=setup();x.state.completed['poi-4']=true;assert.equal(x.model.counts(['poi-4'],x).allCompleted,true);x.state.progress.failed['q-missing']=true;const c=x.model.counts(['poi-4','q-missing'],x);assert.equal(c.unfinished,0);assert.equal(c.allCompleted,false);for(const id of ['q-beast','q-incident']){const p=x.model.prerequisite(id,x.tasks),[view,stage]=p.href.slice(1).split('/');assert.ok(Object.values(x.tasks).some(t=>t.view===view&&t.stages?.some(s=>s.id===stage)));}});
